using System;
using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonSeatEquipmentSetup
    {
        static T Copy<T>(T source,Transform root,Transform target) where T:Component{return target.Find(AnimationUtility.CalculateTransformPath(source.transform,root)).GetComponent<T>();}
        static void Place(RectTransform r,float x,float y,float w,float h){r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);}
        static void Bind(Button b,UnityEngine.Events.UnityAction action){b.onClick=new Button.ButtonClickedEvent();UnityEventTools.AddPersistentListener(b.onClick,action);}
        static Button Button(Button source,Transform root,string name,string text,float x,float y,float w,UnityEngine.Events.UnityAction action){var b=UnityEngine.Object.Instantiate(source,root);b.name=name;Place(b.GetComponent<RectTransform>(),x,y,w,40);b.GetComponentInChildren<Text>().text=text;Bind(b,action);return b;}
        [MenuItem("Cat Cafe/開発用/UI再生成/席の接客設備",false,32)]
        public static void Build()
        {
            var scene=EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();var source=preview.GetComponent<PythonDayOffPanel>();var root=source.panel.transform.parent;var old=root.Find("Seat Equipment");if(old!=null)UnityEngine.Object.DestroyImmediate(old.gameObject);
            var p=preview.GetComponent<PythonSeatEquipmentPanel>() ?? preview.gameObject.AddComponent<PythonSeatEquipmentPanel>();p.panel=UnityEngine.Object.Instantiate(source.panel,root);p.panel.name="Seat Equipment";var s=source.panel.transform;var t=p.panel.transform;
            p.title=Copy(source.title,s,t);p.details=Copy(source.details,s,t);p.notice=Copy(source.notice,s,t);p.confirmationText=Copy(source.confirmationText,s,t);p.confirmation=t.Find(AnimationUtility.CalculateTransformPath(source.confirmation.transform,s)).gameObject;
            p.purchase=Copy(source.proceed,s,t);p.close=Copy(source.close,s,t);p.confirm=Copy(source.confirm,s,t);p.cancel=Copy(source.cancel,s,t);var card=p.purchase.transform.parent;
            p.seatSelector=Button(p.purchase,card,"Select Seat","席",24,78,280,p.NextSeat);p.kindSelector=Button(p.purchase,card,"Select Kind","購入候補",320,78,596,p.NextKind);p.itemSelector=Button(p.purchase,card,"Select Owned","所持品",24,126,892,p.NextItem);
            p.equip=Button(p.purchase,card,"Equip","設置・移動（確認）",252,550,210,p.Equip);p.remove=Button(p.purchase,card,"Remove","取り外す（確認）",480,550,210,p.Remove);
            Place(p.purchase.GetComponent<RectTransform>(),24,550,210,40);Place(p.close.GetComponent<RectTransform>(),708,550,208,40);p.purchase.GetComponentInChildren<Text>().text="購入・設置（確認）";
            var scroll=p.details.transform.parent.parent.GetComponent<ScrollRect>();Place(scroll.GetComponent<RectTransform>(),24,178,892,304);Place(scroll.viewport,6,6,862,292);scroll.verticalScrollbar.GetComponent<RectTransform>().sizeDelta=new Vector2(12,292);
            Bind(p.purchase,p.Purchase);Bind(p.close,p.Close);Bind(p.confirm,p.Confirm);Bind(p.cancel,p.Cancel);p.confirmation.SetActive(false);p.panel.SetActive(false);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);PythonEventListSetup.Build();Debug.Log("CAT_CAFE_SEAT_EQUIPMENT_UI_OK");
        }
        public static void BuildAndVerify()
        {
            Build();var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(client,preview);
            var state=PythonServiceSetup.Sample();state.instance_id="seat-equipment-test";state.can_set_shifts=true;state.closed=false;state.required_action="";
            state.seat_equipment=new PythonSeatEquipment{can_manage=true,details="1席に設備1つ。移動・交換・取り外しは無料。取り外した設備は保管します。\n購入後に資金が残る必要があります。特別行動のテンション・体力消費は変更しません。",seats=new[]{new PythonEquipmentSeat{seat_id="seat-1",item_id="equipment-1",description="おもちゃセット（通常上昇：関心×1.2）"},new PythonEquipmentSeat{seat_id="seat-2",description="設備なし"}},catalog=new[]{new PythonEquipmentKind{kind_id="toys",name="おもちゃセット",effect="通常上昇：関心×1.2",cost=300,funds_after=700,can_purchase=true},new PythonEquipmentKind{kind_id="quiet_space",name="静かな交流スペース",effect="静かな交流の通常行動のみ：関心×1.35",cost=450,funds_after=550,can_purchase=true}},owned=new[]{new PythonOwnedEquipment{item_id="equipment-1",name="おもちゃセット",day=1,cost=300,effect="通常上昇：関心×1.2",seat_id="seat-1"},new PythonOwnedEquipment{item_id="equipment-2",name="くつろぎクッション",day=1,cost=300,effect="通常上昇：テンション×1.2"}}};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});apply();var p=preview.GetComponent<PythonSeatEquipmentPanel>();var list=preview.GetComponent<PythonEventListPanel>();list.Open();if(list.entries.Length!=23 || !list.entries[16].interactable)throw new Exception("Equipment entry missing");list.SeatEquipment();if(!p.panel.activeSelf || list.panel.activeSelf || !p.purchase.interactable || !p.remove.interactable || p.equip.interactable)throw new Exception("Equipment navigation failed");
            Canvas.ForceUpdateCanvases();Capture(preview,"Logs/SeatEquipment.png");p.NextKind();p.Purchase();if(!p.confirmationText.text.Contains("550") || !p.confirmationText.text.Contains("静かな"))throw new Exception("Equipment purchase consequence missing");Canvas.ForceUpdateCanvases();if(p.confirmation.transform.GetSiblingIndex()!=p.confirmation.transform.parent.childCount-1)throw new Exception("Equipment confirmation covered by selection buttons");if(p.confirmationText.preferredHeight>p.confirmationText.rectTransform.rect.height)throw new Exception("Equipment confirmation clipped");Capture(preview,"Logs/SeatEquipmentConfirmation.png");p.Cancel();if(typeof(PythonStateClient).GetField("pending",f).GetValue(client)!=null)throw new Exception("Equipment cancel queued action");
            p.NextItem();p.Equip();if(!p.confirmationText.text.Contains("保管中") || !p.confirmationText.text.Contains("費用：0"))throw new Exception("Equipment exchange missing");p.Cancel();p.Remove();if(!p.confirmationText.text.Contains("取り外し"))throw new Exception("Removal missing");state.revision++;apply();if(p.confirmation.activeSelf)throw new Exception("Stale equipment confirmation retained");p.Disconnect();if(p.purchase.interactable || p.equip.interactable || p.remove.interactable)throw new Exception("Offline equipment enabled");apply();
            state.seat_equipment.can_manage=false;state.seat_equipment.reason="営業準備中に行ってください。";state.revision++;apply();if(p.purchase.interactable || p.remove.interactable || !p.notice.text.Contains("営業準備"))throw new Exception("Equipment gate failed");state.seat_equipment.can_manage=true;state.seat_equipment.reason="";state.seat_equipment.catalog[1].can_purchase=false;state.revision++;apply();if(p.purchase.interactable || !p.equip.interactable)throw new Exception("Free arrangement blocked by funds");
            p.Close();state.can_set_shifts=false;state.seats=new[]{new PythonSeatState{seat_id="seat-1",equipment_name="おもちゃセット",equipment_description="おもちゃセット（通常上昇：関心×1.2）"},new PythonSeatState{seat_id="seat-2",equipment_name="設備なし",equipment_description="設備なし"}};state.customers=new PythonCustomerState[0];state.revision++;apply();var service=preview.GetComponent<PythonServiceScreen>();service.ShowSeats();if(!service.GetSeatCard(0).stateText.text.Contains("おもちゃセット"))throw new Exception("Seat equipment label missing");Capture(preview,"Logs/SeatEquipmentSeats.png");
            state.instance_id="loaded";state.can_set_shifts=true;apply();if(p.panel.activeSelf)throw new Exception("Equipment retained across load");state.seat_equipment.catalog[0].can_purchase=true;state.seat_equipment.catalog[1].can_purchase=true;p.Open();p.NextSeat();p.NextKind();p.Purchase();p.Confirm();var queued=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);if(queued==null || queued.kind!="purchase_seat_equipment" || queued.target_type!="seat-2" || queued.choice!="quiet_space" || p.purchase.interactable)throw new Exception("Equipment purchase queue failed");typeof(PythonStateClient).GetField("pending",f).SetValue(client,null);state.revision++;apply();p.Equip();p.Confirm();queued=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);if(queued?.kind!="equip_seat" || queued.choice!="equipment-1" || queued.target_type!="seat-2")throw new Exception("Equipment move queue failed");
            typeof(PythonStateClient).GetField("pending",f).SetValue(client,null);state.revision++;apply();p.NextSeat();p.Remove();p.Confirm();queued=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);if(queued?.kind!="equip_seat" || queued.choice!="" || queued.target_type!="seat-1")throw new Exception("Equipment removal queue failed");Debug.Log("CAT_CAFE_SEAT_EQUIPMENT_DISPLAY_OK");
        }
        static void Capture(ContentPreview preview,string path){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{preview,path});}
    }
